// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router gin.IRouter, si ServerInterface, options GinServerOptions) {
	errorHandler := options.ErrorHandler
	if errorHandler == nil {
		errorHandler = func(c *gin.Context, err error, statusCode int) {
			c.JSON(statusCode, gin.H{"msg": err.Error()})
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandler:       errorHandler,
	}

	router.GET(options.BaseURL+"/api/tasks", wrapper.ListTasks)
	router.GET(options.BaseURL+"/api/tasks/:taskId", wrapper.GetTask)
	router.POST(options.BaseURL+"/api/tasks/:taskId/cancel", wrapper.CancelTask)
	router.GET(options.BaseURL+"/api/tasks/:taskId/events", wrapper.ListTaskEvents)
	router.GET(options.BaseURL+"/api/tasks/:taskId/logs", wrapper.ListTaskLogs)
	router.GET(options.BaseURL+"/api/tasks/:taskId/stages", wrapper.ListTaskStages)
	router.POST(options.BaseURL+"/api/tasks/:taskId/stages/:stageId/retry", wrapper.RetryTaskStage)
}

